 values('stored_storm_staff','Посох Накопленной Грозы','Потраченная мана накапливает грозовой заряд. После достаточного расхода следующий прямой боевой спелл вызывает дополнительный удар молнией.','weapon'::item_category,'unique'::item_rarity,'weapon'::item_equip_group,false,1,'{"intellect":6,"luck":2}'::jsonb,'[{"type":"mana_charge_burst","mana_threshold":60,"burst_percent":35}]'::jsonb,0,7,false,'blunt','{"lightning":15}'::jsonb,'Посох Накопленной Грозы','Потраченная мана накапливает грозовой заряд. После достаточного расхода следующий прямой боевой спелл вызывает дополнительный удар молнией.','mana_charge_burst',60,'{"lightning":7}'::jsonb,8,'hybrid','staff',0)
