 values('living_bark_cuirass','Кираса Живой Коры','Кора реагирует на яд, кровотечение и проклятия владельца: пока негативные эффекты активны, защита растёт; очищение возвращает часть потерянной жизненной силы.','armor'::item_category,'unique'::item_rarity,'chest'::item_equip_group,false,1,'{"vitality":6}'::jsonb,'[{"type":"debuff_bark","defense_percent_per_debuff":6,"max_stacks":3,"cleanse_heal_max_hp_percent":6}]'::jsonb,0,8,false,null,'{"earth":15,"slashing":8}'::jsonb,'Кираса Живой Коры','Кора реагирует на яд, кровотечение и проклятия владельца: пока негативные эффекты активны, защита растёт; очищение возвращает часть потерянной жизненной силы.','debuff_bark',6,'{}'::jsonb,0,null,null,0)
