 values('crystal_vein_bow','Лук Хрустальной Жилы','Хрустальная тетива поощряет ритм: быстрый выстрел оставляет Трещину, а полный натяг раскалывает её усиленным бронебойным попаданием.','weapon'::item_category,'unique'::item_rarity,'weapon'::item_equip_group,false,1,'{"agility":6,"luck":2}'::jsonb,'[{"type":"bow_alternation","crack_bonus_percent":35,"bonus_armor_penetration_percent":30}]'::jsonb,0,9,false,'piercing','{"ice":8}'::jsonb,'Лук Хрустальной Жилы','Хрустальная тетива поощряет ритм: быстрый выстрел оставляет Трещину, а полный натяг раскалывает её усиленным бронебойным попаданием.','bow_alternation',35,'{}'::jsonb,17,'agility','short_bow',32)
