 values('drowned_queen_tear','Слеза Утонувшей Королевы','Лечение союзника на критическом уровне ОЗ снимает один негативный эффект и даёт небольшой защитный барьер. На одной цели эффект имеет внутреннюю перезарядку.','accessory'::item_category,'unique'::item_rarity,'accessory'::item_equip_group,false,1,'{"intellect":5,"vitality":2}'::jsonb,'[{"type":"critical_heal_cleanse","trigger_hp_percent":35,"barrier_max_hp_percent":10,"cooldown_rounds":3}]'::jsonb,0,12,false,null,'{"water":18}'::jsonb,'Слеза Утонувшей Королевы','Лечение союзника на критическом уровне ОЗ снимает один негативный эффект и даёт небольшой защитный барьер. На одной цели эффект имеет внутреннюю перезарядку.','critical_heal_cleanse',35,'{}'::jsonb,0,null,null,0)
