 values('white_silence_mantle','Мантия Белой Тишины','Мантия требует чередовать роль мага: поддерживающее заклинание усиливает следующую атаку, а атакующее — следующее лечение или щит.','armor'::item_category,'unique'::item_rarity,'chest'::item_equip_group,false,1,'{"intellect":7,"vitality":3}'::jsonb,'[{"type":"spell_role_alternation","damage_bonus_percent":18,"support_bonus_percent":20}]'::jsonb,0,14,false,null,'{"ice":20,"moon":10}'::jsonb,'Мантия Белой Тишины','Мантия требует чередовать роль мага: поддерживающее заклинание усиливает следующую атаку, а атакующее — следующее лечение или щит.','spell_role_alternation',18,'{"ice":5}'::jsonb,0,null,null,0)
