 values('deep_tide_hide','Шкура Глубинного Прилива','После первого серьёзного элементального удара шкура адаптируется к этому типу энергии и временно повышает соответствующее сопротивление.','armor'::item_category,'legendary'::item_rarity,'chest'::item_equip_group,false,1,'{"vitality":6,"agility":2}'::jsonb,'[{"type":"adaptive_resist","resistance_bonus_percent":25,"duration_rounds":3,"trigger_min_damage_percent":8}]'::jsonb,0,10,false,null,'{"water":12}'::jsonb,'Шкура Глубинного Прилива','После первого серьёзного элементального удара шкура адаптируется к этому типу энергии и временно повышает соответствующее сопротивление.','adaptive_resist',25,'{}'::jsonb,0,null,null,0)
